import sys

lines = sys.stdin.read().splitlines()
nums = list(map(int, lines[0].split()))
k = int(lines[1])

def parts_needed(cap):
    parts, current = 1, 0
    for x in nums:
        if current + x > cap:
            parts += 1
            current = 0
        current += x
    return parts

lo, hi = max(nums), sum(nums)
while lo < hi:
    mid = (lo + hi) // 2
    if parts_needed(mid) <= k:
        hi = mid
    else:
        lo = mid + 1
print(lo)

import sys
from collections import defaultdict, deque

lines = sys.stdin.read().splitlines()
begin, end = lines[0], lines[1]
words = set(lines[2].split())

if end not in words:
    print(0)
else:
    buckets = defaultdict(list)
    for word in words | {begin}:
        for i in range(len(word)):
            buckets[word[:i] + "*" + word[i + 1:]].append(word)

    queue = deque([(begin, 1)])
    seen = {begin}
    answer = 0
    while queue:
        word, dist = queue.popleft()
        if word == end:
            answer = dist
            break
        for i in range(len(word)):
            for nxt in buckets[word[:i] + "*" + word[i + 1:]]:
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append((nxt, dist + 1))
    print(answer)

