import sys

lines = sys.stdin.read().splitlines()
n = int(lines[0])
parent = {}

def find(x):
    parent.setdefault(x, x)
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union(a, b):
    ra, rb = find(a), find(b)
    if ra != rb:
        parent[ra] = rb

for i in range(1, n + 1):
    x, y = map(int, lines[i].split())
    union(("row", x), ("col", y))

components = {find(node) for node in parent}
print(n - len(components))
